import {VERSION,SYSTEMS,CLASSES,SPECIES,BACKGROUNDS,BACKGROUND24,SKILLS,ARMORS,WEAPONS,CONDITIONS,FEATS,STYLES,SPELLS,isDnd,uid,clone,integer,text,mod,signed,derive,totalLevel,attackBonus,attackDamageBonus,classLevelChoices,subclassOptions,multiclassWarnings} from './lib/rules.js';
import {leveledCharacter} from './lib/engine.js';
import {Store,saveConfig} from './lib/store.js';
const $=s=>document.querySelector(s),e=value=>String(value??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icons={die:'M12 2 21 7v10l-9 5-9-5V7l9-5Zm0 0L8 10m4-8 4 8M3 7l5 3h8l5-3M8 10l4 9 4-9M3 17l9 2 9-2m-9 2v3',sword:'m14 3 7 0 0 7-11 11-7-7L14 3Zm-9 9 7 7M3 21l4-4m-4 0 4 4',crown:'m3 6 4 4 5-7 5 7 4-4-2 13H5L3 6Zm3 9h12',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',plus:'M12 4v16M4 12h16',close:'m6 6 12 12M18 6 6 18',book:'M12 5C8 2 4 3 2 4v16c3-2 7-2 10 0 3-2 7-2 10 0V4c-2-1-6-2-10 1Zm0 0v15',message:'M21 4H3v13h5l4 4v-4h9V4Z',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6L12 2Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m14-7a4 4 0 0 1 6 4v3M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm8-7a4 4 0 0 1 0 7',gear:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3Zm3 5a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',exit:'M9 3H3v18h6m5-14 5 5-5 5m-7-5h13',edit:'m16 3 5 5-12 12-6 1 1-6L16 3Zm-2 2 5 5',image:'M3 3h18v18H3V3Zm0 13 5-5 5 5 3-3 5 5M15 7h.01',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',heart:'M20 4c-4-3-8 2-8 2s-4-5-8-2c-6 5 1 12 8 17 7-5 14-12 8-17Z',check:'m4 12 5 5L20 6',refresh:'M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6m-5 4a8 8 0 0 0 14 5l3-3m0 6v-6h-6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',chevron:'m8 4 8 8-8 8',clock:'M12 8v5l3 2m-3 7a10 10 0 1 0 0-20 10 10 0 0 0 0 20Z',list:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',send:'m22 2-7 20-4-9L2 9 22 2Zm0 0L11 13',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13Z',eye:'M1 12S5 4 12 4s11 8 11 8-4 8-11 8S1 12 1 12Zm11-4a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z',bolt:'m13 2-9 12h7l-1 8 10-13h-7l0-7Z',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',home:'M2 11 12 2l10 9M5 9v13h14V9m-10 13v-8h6v8'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.die}"/></svg>`;
const button=(label,action,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const opts=(list,selected='',blank='')=>(blank?`<option value="">${e(blank)}</option>`:'')+list.map(x=>{const val=typeof x==='object'?x.value:x,label=typeof x==='object'?x.label:x;return `<option value="${e(val)}" ${String(selected)===String(val)?'selected':''}>${e(label)}</option>`;}).join('');
function customSelect(name,label,list,value='',blank='Choose…'){
 const other=value&&!list.some(x=>String(typeof x==='object'?x.value:x)===String(value));
 return `<label>${e(label)}<select name="${name}" data-custom="${name}">${opts(list,other?'__other':value,blank)}<option value="__other" ${other?'selected':''}>Other / Custom…</option></select><input class="custom-input" name="${name}Other" placeholder="Enter your own ${e(label.toLowerCase())}" maxlength="120" ${other?'':'hidden disabled'} value="${other?e(value):''}"></label>`;
}
function cv(form,name){const v=form.elements.namedItem(name)?.value;return v==='__other'?form.elements.namedItem(name+'Other')?.value?.trim()||'':v??'';}
const num=(form,name,def=0)=>Number(cv(form,name)||def);
const checked=(form,name)=>!!form.elements.namedItem(name)?.checked;
const initials=name=>(name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const time=at=>new Date(at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});
const blank=(title,body,ico='die')=>`<div class="empty">${icon(ico,'lg')}<h3>${e(title)}</h3><p class="small mb0">${e(body)}</p></div>`;
const formFooter=(label='Save changes')=>`<div class="form-error" role="alert"></div><div class="modal-footer">${button('Cancel','close','ghost')}<button class="btn primary" type="submit">${e(label)}</button></div>`;
let store,V={profiles:[],games:[],characters:[],rolls:[],messages:[],requests:[],online:[],targets:{}},route='home',role='player',nav='character',sheetTab='combat',charId='',advantage='normal',chatChannel='party',chatRecipient='',chatDraft='',lastSignature='',syncBusy=false,pollTimer=null,toastTimer,overlayTimer,queue=[],overlayActive=false,modalData={},wizard=null,contextGame=null,pollFailures=0;
const seen=new Set();
function currentChar(){return V.characters?.find(c=>c.id===charId)||V.characters?.[0]||null;}
function playerName(id){return V.profiles?.find(p=>p.id===id)?.name||'Unknown player';}
function currentProfile(){return V.profiles.find(p=>p.id===V.session?.profileId);}
function isGM(){return V.session?.role==='gm';}
function toast(message,error=false){const t=$('#toast');t.textContent=message;t.className='visible'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.className='',error?6500:3500);}
function showModal(title,content,data={}){modalData=data;const m=$('#modal');m.innerHTML=`<div class="modal-header"><h2 id="modal-title">${e(title)}</h2>${button(icon('close'),'close','icon-only ghost','aria-label="Close dialog"')}</div><div class="modal-content">${content}</div>`;if(!m.open)m.showModal();m.scrollTop=0;}
function closeModal(){$('#modal').close();modalData={};wizard=null;lastSignature='';render();}
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function fileName(name){return text(name,70).replace(/[^a-z0-9-_]+/gi,'_')||'character';}
function primeRolls(state){seen.clear();for(const r of state.rolls||[])if(r.outcome&&r.outcome!=='pending')seen.add(r.id+':'+r.resolvedAt);queue=[];hideOverlay();}
function observeRolls(state){
 if(contextGame!==state.currentGame?.id){contextGame=state.currentGame?.id||null;primeRolls(state);return;}
 for(const r of state.rolls||[]){if(r.kind!=='attack'||!['hit','miss'].includes(r.outcome))continue;const key=r.id+':'+r.resolvedAt;if(seen.has(key))continue;seen.add(key);
  if(state.session?.role==='gm'||r.playerId===state.session?.profileId)queue.push(r);
 }
 if(seen.size>1000){const arr=[...seen].slice(-500);seen.clear();arr.forEach(x=>seen.add(x));}showNextOverlay();
}
function showNextOverlay(){if(overlayActive||!queue.length)return;const r=queue.shift(),el=$('#roll-overlay');overlayActive=true;el.hidden=false;if(!el.open)el.showModal();el.className=r.outcome;el.innerHTML=`<div class="outcome-ring"></div><div class="outcome-caption">${e(r.characterName)} · ${e(r.label)}</div><div class="outcome-title">${r.outcome==='hit'?'HIT':'MISS'}</div><div class="outcome-label">${r.critical?'Critical hit':r.outcome==='hit'?'Your attack connects.':'Your attack misses.'}</div><div class="outcome-total">${e(r.total)}${isGM()&&r.ac!==undefined?` <span class="muted">vs AC ${e(r.ac)}</span>`:''}</div><div class="outcome-hint">Tap anywhere to continue</div>`;el.focus({preventScroll:true});clearTimeout(overlayTimer);overlayTimer=setTimeout(hideOverlay,2400);}
function hideOverlay(){clearTimeout(overlayTimer);$('#roll-overlay').close();$('#roll-overlay').hidden=true;overlayActive=false;if(queue.length)setTimeout(showNextOverlay,100);}
function accept(response,{force=false}={}){const state=response.state;if(!state)return;observeRolls(state);V=state;if(V.session)role=V.session.role;if(!V.characters.some(c=>c.id===charId))charId=V.characters[0]?.id||'';if(force)lastSignature='';render();}
async function perform(action,payload={},options={}){const response=await store.request(action,payload);accept(response,{force:true});if(options.close)closeModal();return response.result||{};}
async function sync(){if(syncBusy||document.hidden)return;syncBusy=true;try{const res=await store.sync();pollFailures=0;accept(res);}catch(error){pollFailures++;store.offline=true;if(pollFailures===1&&store.live)toast(error.message,true);render(true);}finally{syncBusy=false;}}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(sync,store.live?store.config.pollMs||2500:2000);if(store.channel)store.channel.onmessage=()=>{if(!syncBusy)setTimeout(sync,60);};}
function brand(){return `<button class="brand" data-action="home" type="button"><span class="brand-mark">${icon('die','lg')}</span><span><span class="brand-name">TABLEBOUND</span><span class="brand-sub" style="display:block">A place for your party</span></span></button>`;}
function modePill(){return `<span class="pill ${store?.live?'':'gold'}"><span class="dot"></span>${store?.live?'Connected table':'Local demo'}</span>`;}
function landingHeader(){return `<header class="landing-header">${brand()}<div class="row gap6">${modePill()}${button(icon('gear'),'connection','ghost icon-only','aria-label="Connection settings"')}</div></header>`;}
function homeView(){return `<div class="landing">${landingHeader()}<main><div class="landing-main"><div><div class="eyebrow">Characters. Dice. Stories.</div><h1 class="hero-title">Every character.<br><em>One table.</em></h1><p class="hero-copy">Bring your character. Gather your party. Let the story unfold, and leave the numbers to the dice.</p><div class="row wrap gap6"><span class="pill neutral">5E · 2014 & 2024</span><span class="pill neutral">Custom character sheets</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit"></div><svg viewBox="0 0 240 280" fill="none"><path d="M120 12 222 72v128L120 264 18 200V72L120 12Z" stroke="currentColor" stroke-width="1.4"/><path d="M120 12 67 105 18 72m49 33h106l49-33m-49 33L120 12M67 105l53 116 53-116M18 200l102 21 102-21m-102 21v43" stroke="currentColor" stroke-width="1.4"/><path d="m67 105 53 23 53-23m-53 23v93" stroke="currentColor" opacity=".25"/><text x="120" y="171" text-anchor="middle" font-family="Georgia,serif" font-size="45" fill="currentColor">20</text></svg><span class="art-label">YOUR NEXT CHAPTER STARTS HERE</span></div></div><div class="eyebrow" style="margin-bottom:12px">Take your seat</div><div class="role-cards"><button class="role-card" type="button" data-action="role" data-role="player"><span class="role-icon">${icon('sword','lg')}</span><span><h2>Player</h2><p>Build your character, roll your dice, and step into the adventure.</p></span><span class="arrow">${icon('arrow')}</span></button><button class="role-card" type="button" data-action="role" data-role="gm"><span class="role-icon">${icon('crown','lg')}</span><span><h2>DM / GM</h2><p>Gather the party, set the stakes, and bring the world to life.</p></span><span class="arrow">${icon('arrow')}</span></button></div>${!store?.live?`<div class="notice info mb">${icon('die')} <strong>Local demo is ready.</strong> Sample characters are included. Two tabs in this browser share the demo; different devices need your Supabase connection.</div>`:''}</main><footer class="landing-footer"><span>No email or password. Choose a name and a game.</span><span>${button('Rules & coverage','coverage','subtle small')} <span class="muted">v${VERSION}</span></span></footer></div>`;}
function steps(active){return `<div class="stepper"><span class="${active===1?'current':''}">01 &nbsp; Your role</span><span>›</span><span class="${active===2?'current':''}">02 &nbsp; Your name</span><span>›</span><span class="${active===3?'current':''}">03 &nbsp; Your game</span></div>`;}
function namesView(){const names=V.profiles.filter(p=>p.role===role);return `<div class="landing">${landingHeader()}<main class="step-page">${steps(2)}<div class="row between mb">${button(icon('back')+' Back','home','subtle small')}<span class="pill gold">${role==='gm'?'DM / GM':'Player'}</span></div><div class="eyebrow">Welcome to the table</div><h1>What should we call you?</h1><p class="muted">Choose your saved name, or add a new one. Your character’s name comes later.</p><div class="grid3 mt">${names.map(p=>`<button type="button" class="card name-card" data-action="select-profile" data-id="${e(p.id)}"><span class="avatar">${e(initials(p.name))}</span><span class="grow"><strong>${e(p.name)}</strong><small>${role==='gm'?'Game master':'Player'}</small></span>${icon('chevron')}</button>`).join('')}</div><form id="new-profile" class="new-name"><label>New ${role==='gm'?'GM':'player'} name<input name="name" placeholder="Enter a name" maxlength="60" autocomplete="nickname" required></label><button type="submit" class="btn primary">${icon('plus')} Create name</button></form><p class="field-help mt">Trusted-table entry: choosing a name does not verify identity. Anyone with this app’s access can select an existing name, including a GM name.</p><div class="form-error" role="alert"></div></main></div>`;}
function gamesView(activeOnly=false){const games=V.games.filter(g=>!activeOnly||g.activeGMs.length);return `<div class="landing">${landingHeader()}<main class="step-page">${steps(3)}<div class="page-title"><div><div class="eyebrow">${e(currentProfile()?.name||'Your table')} · ${role==='gm'?'DM / GM':'Player'}</div><h1>${activeOnly?'Find an active GM.':'Choose your next chapter.'}</h1><p>${activeOnly?'These games have a GM connected right now.':'Your characters and stories stay with their own games.'}</p></div>${role==='gm'?button(icon('plus')+' Create game','create-game','primary'):button(activeOnly?'Show all games':'Active GMs only',activeOnly?'all-games':'active-games','ghost')}</div><div class="grid3">${games.map(game=>`<article class="card game-card"><div class="row between"><span class="game-system">${e(SYSTEMS[game.system]?.short||game.system)}</span><span class="pill ${game.activeGMs.length?'':'neutral'}"><span class="dot"></span>${game.activeGMs.length?'GM active':'GM offline'}</span></div><div class="game-symbol">${icon(game.system==='coc7'?'eye':game.system==='dnd14'?'sword':'crown','lg')}</div><h2>${e(game.name)}</h2><p>${e(game.description||'A fresh page, waiting for your party.')}</p><div class="small muted">${game.activeGMs.length?'GM: '+e(game.activeGMs.map(p=>p.name).join(', ')):`${game.characterCount} saved character${game.characterCount===1?'':'s'}`}</div><button type="button" class="btn ${game.activeGMs.length?'primary':'ghost'} wide" data-action="join-game" data-id="${e(game.id)}">Enter game ${icon('arrow')}</button></article>`).join('')}</div>${!games.length?blank(activeOnly?'No GMs are active right now.':'No games yet.',activeOnly?'You can still open any saved game and work on your character.':'Choose DM / GM to create the first game.','crown'):''}<div class="row between mt">${button(icon('back')+' Choose another name','choose-name','subtle')}<p class="small muted m0">Games remain available when the GM is offline.</p></div></main></div>`;}
const PLAYER_NAV=[['character','book','Character'],['dice','die','Dice tray'],['messages','message','Messages'],['journal','edit','Journal']];
const GM_NAV=[['table','crown','GM table'],['rolls','die','Roll feed'],['messages','message','Messages'],['encounter','sword','Encounter'],['gmnotes','book','GM notes']];
function navHTML(mobile=false){const items=isGM()?GM_NAV:PLAYER_NAV;return items.map(([id,ico,name])=>`<button type="button" class="${mobile?'':'nav-btn '}${nav===id?'active':''}" data-action="nav" data-nav="${id}">${icon(ico)}<span>${mobile&&name==='GM table'?'Table':name}</span></button>`).join('');}
function shellView(){const g=V.currentGame;if(!g)return gamesView();const gm=(V.games.find(x=>x.id===g.id)?.activeGMs||[]),activeCount=V.games.filter(x=>x.activeGMs.length).length,profile=currentProfile();return `<div class="shell"><aside class="sidebar">${brand()}<div class="nav-label">${isGM()?'BEHIND THE SCREEN':'YOUR ADVENTURE'}</div>${navHTML()}<div class="sidebar-bottom">${button(icon('refresh')+' Switch game','all-games','ghost wide')}${button(icon('gear')+' Connection','connection','subtle wide mt8')}${button('Rules & coverage','coverage','subtle wide small')}<div class="identity row"><span class="avatar">${e(initials(profile?.name))}</span><div class="grow"><strong>${e(profile?.name||'Guest')}</strong><small>${isGM()?'DM / GM':'Player'}</small></div>${button(icon('exit'),'choose-name','subtle icon-only','aria-label="Change name"')}</div></div></aside><div class="workspace">${store.offline?'<div class="offline-banner">Connection interrupted. Showing last synced data. Refresh before repeating an action.</div>':''}<header class="topbar"><div><h3>${e(g.name)}</h3><div class="small muted">${e(SYSTEMS[g.system]?.short)} <span style="padding:0 5px">·</span> <span class="${gm.length?'success':''}">${gm.length?'GM active: '+e(gm.map(p=>p.name).join(', ')):'No active GM'}</span>${!store.live?' <span class="gold">· Local demo</span>':''}</div></div><div class="row game-actions">${!isGM()&&!gm.length?button(icon('people')+` Find active GM${activeCount?' · '+activeCount:''}`,'active-games','primary'):button(icon('refresh')+' Switch game','all-games','ghost')}${isGM()?button(icon('gear'),'game-settings','ghost icon-only','aria-label="Game settings"'):''}</div></header><main class="main">${workspaceContent()}</main></div><nav class="mobile-nav" aria-label="Main navigation">${navHTML(true)}<button type="button" data-action="more">${icon('gear')}<span>More</span></button></nav></div>`;}
function workspaceContent(){if(nav==='character')return characterView();if(nav==='dice')return diceView();if(nav==='messages')return messagesView();if(nav==='journal')return journalView();if(nav==='table')return gmView();if(nav==='rolls')return rollFeedView();if(nav==='encounter')return encounterView();if(nav==='gmnotes')return gmNotesView();return '';}
function render(force=false){
 if(!$('#app'))return;
 if(!force&&$('#modal').open)return;
 if(!force&&['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&document.activeElement.closest('#app'))return;
 const {now,...stable}=V;const signature=JSON.stringify([stable,route,nav,sheetTab,charId,advantage,chatChannel,chatRecipient,store?.offline]);if(!force&&signature===lastSignature)return;lastSignature=signature;
 const html=route==='home'?homeView():route==='names'?namesView():route==='games'||route==='active-games'?gamesView(route==='active-games'):shellView();$('#app').innerHTML=html;
 if(nav==='messages'&&route==='dashboard'){const list=$('.message-list');if(list)list.scrollTop=list.scrollHeight;const input=$('#message-body');if(input)input.value=chatDraft;}
}
function characterPicker(){return `<div class="row wrap"><label class="m0 char-switch"><span class="sr-only">Selected character</span><select id="char-picker" style="margin:0">${opts(V.characters.map(c=>({value:c.id,label:c.name})),charId)}</select></label>${button(icon('plus')+' New character','new-character','ghost')}</div>`;}
function requestCards(c){return V.requests.filter(r=>r.status==='open'&&r.playerId===V.session.profileId).map(r=>`<div class="card request-card row between"><div class="grow"><strong>${icon('crown')} GM requests: ${e(r.label)}</strong><p class="m0">${e(r.formula)} · Select the appropriate character first.</p></div>${button(icon('die')+' Roll','requested-roll','primary',`data-id="${e(r.id)}" ${c?'':'disabled'}`)}</div>`).join('');}
function characterView(){const c=currentChar();return `<div class="page-title"><div><div class="eyebrow">Your character</div><h1>Ready for the next chapter.</h1><p>Your sheet, your choices, your story.</p></div>${characterPicker()}</div>${requestCards(c)}${!c?`<div class="card">${blank('Your adventure needs a character.','Start with a rules template, then make it your own.','book')}${button(icon('plus')+' Create character','new-character','primary wide')}${button(icon('upload')+' Import character','import-character','ghost wide mt8')}</div>`:`<div class="content-grid"><section>${characterSheet(c)}</section><aside class="right-column">${quickFeed()}<div class="notice mt">${icon('shield')} <strong>Meet or beat.</strong> Tell your GM what you’re attacking. They set the target AC. Your attack total handles the rest.</div>${!isDnd(c.system)?'<div class="notice mt">Editable system template. Numeric fields and success rules need GM review; complete system progression is not automated.</div>':''}</aside></div>`}`;}
function portraitHTML(c){return `<div class="portrait">${c.portrait?`<img src="${e(c.portrait)}" alt="Portrait of ${e(c.name)}">`:icon('shield','xl')}${button(icon('image'),'portrait','icon-only small',`data-id="${e(c.id)}" aria-label="Character portrait"`)}</div>`;}
function characterSheet(c){const d=derive(c),hp=Math.max(0,d.maxHP-(c.damage||0)),overrideCount=Object.values(c.overrides||{}).filter(o=>o.mode!=='auto').length;return `<div class="card sheet-hero">${portraitHTML(c)}<div class="grow"><div class="row wrap gap6"><span class="pill gold">${isDnd(c.system)?`LEVEL ${d.level}`:SYSTEMS[c.system].level?`LEVEL ${c.level}`:`ADVANCE ${Math.max(0,c.level-1)}`}</span>${overrideCount?`<span class="pill neutral">${overrideCount} override${overrideCount===1?'':'s'}</span>`:''}</div><h2>${e(c.name)}</h2><p class="subtitle mb0">${e([c.species,isDnd(c.system)?c.classes.map(x=>x.name+' '+x.level).join(' / '):c.archetype,c.background].filter(Boolean).join(' · '))}</p><div class="row wrap gap6 mt8">${button(icon('edit')+' Edit sheet','edit-character','small ghost',`data-id="${e(c.id)}"`)}${button(icon('spark')+(SYSTEMS[c.system].level?' Level up':' Advance'),'level-up','small primary',`data-id="${e(c.id)}"`)}</div></div></div>${c.pendingLevel?`<div class="notice mt">Level-up waiting for GM approval. The current sheet is unchanged.${isGM()?`<div class="row mt8">${button('Approve','approve-level','primary small',`data-id="${e(c.id)}"`)}${button('Decline','decline-level','ghost small',`data-id="${e(c.id)}"`)}</div>`:''}</div>`:''}<div class="metrics"><div class="metric"><div class="label">Hit points</div><div class="value">${hp}<span class="max"> / ${d.maxHP}</span></div><div class="hp-bar"><span style="width:${clampPercent(hp/d.maxHP*100)}%"></span></div><small>${c.tempHP?`+${c.tempHP} temporary`:'Ready for anything'}</small><div>${button('Adjust HP','hp','small ghost',`data-id="${e(c.id)}"`)}</div></div><div class="metric"><div class="label">Armor class</div><div class="value">${e(d.ac)}</div><small>${e(c.armor||'Manual defense')}</small></div><div class="metric"><div class="label">Initiative</div><div class="value">${signed(d.initiative)}</div>${isDnd(c.system)?button('Roll','skill-roll','small ghost',`data-id="${e(c.id)}" data-skill="Initiative"`):'<small>Manual modifier</small>'}</div><div class="metric"><div class="label">${isDnd(c.system)?'Proficiency':'Progress'}</div><div class="value">${isDnd(c.system)?signed(d.proficiency):e(c.level)}</div><small>${isDnd(c.system)?`${d.attacks} attack${d.attacks===1?'':'s'} / action`:'Manual advancement'}</small></div></div><div class="attribute-grid" ${Object.keys(c.stats).length!==6?'style="grid-template-columns:repeat('+Math.min(6,Object.keys(c.stats).length)+',minmax(0,1fr))"':''}>${Object.entries(c.stats).map(([stat,value])=>`<div class="attribute"><div class="label">${e(stat)}</div><div class="score">${c.system==='swade'?'d':''}${e(value)}</div><div class="modifier">${isDnd(c.system)?signed(mod(value)):'score'}</div></div>`).join('')}</div>${c.conditions.length?`<div class="row wrap gap6 mb">${c.conditions.map(x=>`<button class="condition-chip" data-action="toggle-condition" data-id="${e(c.id)}" data-condition="${e(x)}" title="Remove condition">${e(x)} ×</button>`).join('')}</div>`:''}<div class="tabs" role="tablist">${[['combat','Combat'],['skills','Skills & saves'],['magic','Spells & resources'],['features','Features']].map(([id,label])=>`<button class="tab ${sheetTab===id?'active':''}" data-action="sheet-tab" data-tab="${id}" role="tab" aria-selected="${sheetTab===id}">${label}</button>`).join('')}</div>${sheetTab==='combat'?combatSheet(c,d):sheetTab==='skills'?skillsSheet(c,d):sheetTab==='magic'?magicSheet(c,d):featuresSheet(c,d)}`;}
function clampPercent(n){return Math.max(0,Math.min(100,Number(n)||0));}
function advantageControl(){return `<div class="segmented" aria-label="Roll mode">${[['normal','Normal'],['advantage','Advantage'],['disadvantage','Disadv.']].map(([v,label])=>`<button type="button" class="${advantage===v?'active':''}" data-action="advantage" data-value="${v}">${label}</button>`).join('')}</div>`;}
function combatSheet(c,d){return `<div class="row between wrap"><h2 class="m0">Actions & attacks</h2>${advantageControl()}</div>${c.attacks.map(a=>`<div class="attack-card"><div class="row"><span style="color:var(--gold)">${icon('sword')}</span><div class="grow"><div class="attack-title">${e(a.name)}</div><div class="attack-description">${e(a.damage)}${attackDamageBonus(c,a)?' '+signed(attackDamageBonus(c,a)):''} ${e(a.type||'damage')} ${a.stat?'· '+e(a.stat):''}</div></div><div class="attack-bonus">${c.system==='coc7'?e(a.threshold||50)+'%':c.system==='swade'?'d'+e(a.sides||6):signed(attackBonus(c,a))}</div>${button(icon('edit'),'edit-attack','subtle icon-only small',`data-id="${e(c.id)}" data-attack="${e(a.id)}" aria-label="Edit ${e(a.name)}"`)}</div><div class="attack-actions">${button(icon('die')+' Roll attack','attack','primary',`data-id="${e(c.id)}" data-attack="${e(a.id)}"`)}${button('Damage','damage','ghost',`data-id="${e(c.id)}" data-attack="${e(a.id)}"`)}${isDnd(c.system)?button('Crit dmg','damage','ghost',`data-id="${e(c.id)}" data-attack="${e(a.id)}" data-critical="true"`):''}</div></div>`).join('')}${button(icon('plus')+' Add ability / attack','edit-attack','ghost wide',`data-id="${e(c.id)}"`)}<div class="row wrap mt">${button(icon('heart')+' Conditions','conditions','ghost small',`data-id="${e(c.id)}"`)}${button(icon('moon')+' Short rest','rest','ghost small',`data-id="${e(c.id)}" data-type="short"`)}${button(icon('moon')+' Long rest','rest','ghost small',`data-id="${e(c.id)}" data-type="long"`)}</div>${d.sneakAttack?`<div class="notice mt">Sneak Attack: <strong>${e(d.sneakAttack)}</strong>. Check eligibility at the table; add it through a separate damage roll.</div>`:''}<p class="field-help mt">Attack and damage are separate. Critical damage doubles formula dice, not flat modifiers. Conditions and conditional feature effects are not applied automatically.</p>`;}
function skillsSheet(c,d){if(!isDnd(c.system))return `<div class="notice">This system uses an editable template. Create named ability buttons with your skill modifiers or percentile targets.</div>${button('Add ability','edit-attack','primary mt',`data-id="${e(c.id)}"`)}`;return `<div class="row between mb"><h2 class="m0">Skills</h2>${button('Edit proficiencies','edit-skills','ghost small',`data-id="${e(c.id)}"`)}</div><div class="skill-list">${Object.entries(d.skills).map(([skill,value])=>`<div class="skill"><div><strong>${c.skills[skill]===2?'◆ ':c.skills[skill]===1?'● ':''}${e(skill)}</strong><span class="tag">${SKILLS[skill]}</span></div>${button(signed(value),'skill-roll','small ghost',`data-id="${e(c.id)}" data-skill="${e(skill)}"`)}</div>`).join('')}</div><h2 class="mt">Saving throws</h2><div class="skill-list">${Object.entries(d.saves).map(([skill,value])=>`<div class="skill"><strong>${c.saves.includes(skill)?'● ':''}${e(skill)}</strong>${button(signed(value),'skill-roll','small ghost',`data-id="${e(c.id)}" data-skill="${e(skill)}"`)}</div>`).join('')}</div><p class="field-help mt">● Proficient &nbsp; ◆ Expertise. Roll mode follows Normal / Advantage / Disadvantage on Combat.</p>`;}
function magicSheet(c,d){return `${Object.keys(d.spellcasting).length?`<div class="grid2 mb">${Object.entries(d.spellcasting).map(([name,sc])=>`<div class="card"><div class="eyebrow">${e(name)} · ${e(sc.ability)}</div><div class="row between"><div><small class="muted">Spell attack</small><h2 class="m0">${signed(sc.attack)}</h2></div><div><small class="muted">Save DC</small><h2 class="m0">${e(sc.dc)}</h2></div></div></div>`).join('')}</div>`:''}${d.slots.length||d.pact?`<div class="card mb"><h2>Spell slots</h2>${d.slots.map((count,i)=>`<div class="slot-row"><strong class="small">Level ${i+1}</strong><div class="slot-pips">${Array.from({length:count},(_,j)=>`<span class="pip ${j<count-(c.slotsUsed[i+1]||0)?'':'used'}"></span>`).join('')}</div><div class="row gap6">${button('−','slot','small ghost',`data-id="${e(c.id)}" data-slot="${i+1}" data-delta="1" aria-label="Spend level ${i+1} slot"`)}${button('+','slot','small ghost',`data-id="${e(c.id)}" data-slot="${i+1}" data-delta="-1" aria-label="Restore level ${i+1} slot"`)}</div></div>`).join('')}${d.pact?`<div class="slot-row"><strong class="small">Pact · level ${d.pact.level}</strong><span class="gold">${d.pact.count-(c.pactUsed||0)} / ${d.pact.count}</span><div class="row gap6">${button('−','slot','small ghost',`data-id="${e(c.id)}" data-slot="pact" data-delta="1"`)}${button('+','slot','small ghost',`data-id="${e(c.id)}" data-slot="pact" data-delta="-1"`)}</div></div>`:''}</div>`:''}${d.resources.length?`<div class="card mb"><h2>Class resources</h2>${d.resources.map(r=>`<div class="slot-row"><div><strong class="small">${e(r.name)}</strong><div class="field-help m0">${r.reset==='partial-short'?'Recover 1 on short rest; all on long rest':r.reset+' rest'}</div></div><span class="gold">${r.max-(c.resourcesUsed[r.name]||0)} / ${r.max===999?'∞':r.max}</span><div class="row gap6">${button('−','resource','small ghost',`data-id="${e(c.id)}" data-name="${e(r.name)}" data-delta="1"`)}${button('+','resource','small ghost',`data-id="${e(c.id)}" data-name="${e(r.name)}" data-delta="-1"`)}</div></div>`).join('')}</div>`:''}<div class="row between"><h2 class="m0">Your spells</h2>${button(icon('plus')+' Add spell','add-spell','ghost small',`data-id="${e(c.id)}"`)}</div>${c.spells.length?c.spells.slice().sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name)).map((spell)=>`<div class="spell-row"><div><strong>${e(spell.name)}</strong><div><small>${spell.level===0?'Cantrip':'Level '+spell.level} · ${e(spell.className||'Custom')}${spell.manual?' · manual':''}</small></div></div><div class="row gap6">${spell.level>0?button('Spend slot','cast-spell','small ghost',`data-id="${e(c.id)}" data-level="${spell.level}" data-name="${e(spell.name)}"`):''}${button(icon('trash'),'remove-spell','small subtle icon-only',`data-id="${e(c.id)}" data-name="${e(spell.name)}" data-class="${e(spell.className||'')}" aria-label="Remove spell"`)}</div></div>`).join(''):blank('No spells recorded.','Choose from the starter catalog or add a custom spell.','spark')}<div class="notice mt">The catalog lists spell names and levels, not full spell text. Prepare/know limits, subclass additions, upcasting effects and concentration need review. Slot spending is tracked; effects are resolved at the table.</div>${d.byClass.map(cap=>`<p class="field-help mt8">${e(cap.name)}: ${cap.cantrips} class cantrips · ${cap.prepared} standard prepared/known spells${cap.book?' · '+cap.book+' minimum spellbook entries':''} · maximum class spell level ${cap.maxSpell}. Additional features may alter these counts.</p>`).join('')}`;}
function featuresSheet(c,d){return `<div class="row between mb"><h2 class="m0">Features & choices</h2>${button(icon('plus')+' Add feature','add-feature','small ghost',`data-id="${e(c.id)}"`)}</div>${c.classes.map(x=>x.subclass?`<div class="feature"><strong>${e(x.subclass)}</strong><p>${e(x.name)} subclass. Feature text and conditional effects are reviewed manually.</p></div>`:'').join('')}${c.feats.map(x=>`<div class="feature"><span class="pill gold">Feat</span> <strong>${e(x)}</strong><p>Review its effects and additional selections in your rules source.</p></div>`).join('')}${c.fightingStyle?`<div class="feature"><strong>Fighting style · ${e(c.fightingStyle)}</strong><p>Archery, Defense and marked Dueling modifiers are automated. Other conditional effects are manual.</p></div>`:''}${c.features.map(f=>`<div class="feature"><div class="row between"><strong>${e(f.name)}</strong><span class="pill neutral">${f.manual?'Manual':'Recorded'}</span></div><p>${e(f.notes)}</p></div>`).join('')}<div class="row wrap mt">${button('Review initial class choices','initial-choices','ghost small',`data-id="${e(c.id)}"`)}${button('Undo last level-up','undo-level','ghost small',`data-id="${e(c.id)}" ${c.undo?.length?'':'disabled'}`)}</div><h2 class="mt">Change history</h2>${(c.history||[]).slice(0,15).map(h=>`<div class="feature"><strong class="small">${e(h.what)}</strong><p>${e(playerName(h.who))} · ${new Date(h.at).toLocaleString()}</p></div>`).join('')}`;}
function rollDetails(r){if(r.parts)return r.parts.map(p=>p.constant!==undefined?`${p.sign<0?'−':'+'}${p.constant}`:`${p.sign<0?'−':''}[${p.dice.filter(d=>d.kept).map(d=>d.value).join(', ')}]`).join(' ');if(r.trait)return `Trait ${r.trait.total} · wild ${r.wild.total}`;if(r.dice)return r.dice.map(d=>(d.kept?'':'(')+d.attempts.join('→')+(d.explosions?.length?'!'+d.explosions.join('+'):'')+(d.kept?'':')')).join(', ')+(r.bonus?' '+signed(r.bonus):'');return r.formula||'';}
function rollHTML(r,full=false){return `<article class="roll-item ${e(r.outcome||'')}"><div class="roll-total">${e(r.total)}</div><div class="grow"><div class="row between"><strong>${e(r.characterName)}</strong><time>${time(r.createdAt)}</time></div><p>${e(r.label)}</p><div class="small muted" style="font-size:.7rem">${e(rollDetails(r))}${full&&isGM()&&r.ac!==undefined&&r.ac!==null?' · vs AC '+e(r.ac):''}</div>${r.outcome?`<span class="outcome ${r.outcome==='hit'?'success':r.outcome==='miss'?'danger':'gold'}">${r.outcome==='pending'?'Awaiting GM target':r.critical?'CRITICAL HIT':e(r.outcome)}</span>`:''}${isGM()&&r.outcome==='pending'?`<div class="mt8">${button('Set AC & resolve','resolve-roll','small primary',`data-id="${e(r.id)}"`)}</div>`:''}</div></article>`;}
function quickFeed(){return `<div class="card"><div class="row between"><h3 class="m0">${icon('clock')} At the table</h3><span class="pill neutral">Live feed</span></div>${V.rolls.length?V.rolls.slice(-8).reverse().map(r=>rollHTML(r)).join(''):'<div class="feed-empty">The story starts with a roll.<br>Your party’s rolls will appear here.</div>'}</div>`;}
function diceView(){const c=currentChar(),rules=V.currentGame?.settings?.statLock?V.currentGame.settings.statRules:{count:4,sides:6,reroll:0,repeat:false,keep:'dropLowest',keepCount:1,bonus:0};return `<div class="page-title"><div><div class="eyebrow">Let fate decide</div><h1>The dice tray.</h1><p>Roll it. Inspect it. Give the total a home.</p></div>${characterPicker()}</div>${!c?`<div class="card">${blank('Choose a character first.','Stat totals need a character sheet to belong to.','die')}${button('Create character','new-character','primary wide')}</div>`:`<div class="content-grid"><section><form id="stat-roll" class="card"><div class="row between mb"><h2 class="m0">Roll an ability score</h2>${V.currentGame.settings.statLock?'<span class="pill gold">GM rules locked</span>':''}</div><div class="grid3">${customSelect('sides','Die',[{value:4,label:'d4'},{value:6,label:'d6'},{value:8,label:'d8'},{value:10,label:'d10'},{value:12,label:'d12'},{value:20,label:'d20'},{value:100,label:'d100'}],rules.sides)}<label>How many dice?<input name="count" type="number" min="1" max="100" value="${rules.count}" required></label><label>Reroll<select name="reroll">${opts([{value:0,label:'Nothing'},{value:1,label:'1s'},{value:2,label:'1s and 2s'}],rules.reroll)}</select></label><label>Keep / drop<select name="keep">${opts([{value:'all',label:'Keep everything'},{value:'dropLowest',label:'Drop lowest'},{value:'dropHighest',label:'Drop highest'},{value:'highest',label:'Keep highest'},{value:'lowest',label:'Keep lowest'}],rules.keep)}</select></label><label>How many to keep / drop?<input name="keepCount" type="number" min="1" max="100" value="${rules.keepCount||1}" required></label><label>Flat modifier<input name="bonus" type="number" min="-10000" max="10000" value="${rules.bonus||0}"></label></div><label class="check-label"><input name="repeat" type="checkbox" ${rules.repeat?'checked':''}> Keep rerolling until the result is allowed. Otherwise reroll each die only once.</label><div class="form-error" role="alert"></div><button type="submit" class="btn primary wide">${icon('die')} Roll for ${e(c.name)}</button>${V.currentGame.settings.statLock?'<p class="field-help mt8">The server uses the GM’s saved rules, regardless of changes to these controls.</p>':''}</form><div class="row between mt mb"><h2 class="m0">Unassigned totals</h2><span class="pill neutral">${c.statPool.length} available</span></div><div class="roll-pool">${c.statPool.map(p=>`<div class="card pool-card"><div class="row between"><span class="pool-total">${p.total}</span><span class="small muted">${p.roll.count}d${p.roll.sides}</span>${button(icon('trash'),'discard-stat','small subtle icon-only',`data-id="${e(p.id)}" aria-label="Discard total"`)}</div><div class="dice-pieces">${p.roll.dice.map(d=>`<span class="die ${d.kept?'':'dropped'}">${d.value}${d.attempts.length>1?`<small><del>${d.attempts.slice(0,-1).join(' → ')}</del></small>`:''}</span>`).join('')}</div><form class="assign-form" data-pool="${e(p.id)}"><label>Assign to stat<select name="stat" required>${opts(Object.keys(c.stats),'','Choose a stat')}</select></label><button type="submit" class="btn ghost wide">Assign ${p.total} ${icon('arrow')}</button></form></div>`).join('')}</div>${!c.statPool.length?blank('No unassigned rolls yet.','Roll above, then choose which stat receives the total.','die'):''}<form id="free-roll" class="card mt"><h2>Anything else?</h2><div class="grid2"><label>Roll name<input name="label" value="Custom roll" maxlength="100"></label><label>Formula<input name="formula" value="2d6 + 3" maxlength="100" required></label></div><button type="submit" class="btn ghost wide">${icon('die')} Roll formula</button><p class="field-help mt8 mb0">Supports addition and subtraction, for example 1d20 + 5 or 2d6 + 1d4 − 2 (use a normal hyphen).</p></form></section><aside class="right-column">${quickFeed()}</aside></div>`}`;}
function messagesView(){const selected=V.messages.filter(m=>chatChannel==='party'?m.channel==='party':m.channel==='gm'&&(!isGM()||!chatRecipient||m.from===chatRecipient||m.to===chatRecipient));const players=V.profiles.filter(p=>V.currentGame.members.includes(p.id));return `<div class="page-title"><div><div class="eyebrow">Keep the conversation going</div><h1>At the table.</h1><p>Party messages and private conversations with the GM.</p></div><div class="segmented">${[['party','Party chat'],['gm',isGM()?'Player whispers':'Whisper to GM']].map(([id,label])=>`<button class="${chatChannel===id?'active':''}" data-action="chat-channel" data-channel="${id}">${label}</button>`).join('')}</div></div><div class="card">${chatChannel==='gm'&&isGM()?`<label>Conversation with<select id="chat-recipient">${opts(players.map(p=>({value:p.id,label:p.name})),chatRecipient,'Choose a player')}</select></label>`:''}<div class="message-list">${selected.length?selected.map(m=>`<div class="bubble ${m.from===V.session.profileId?'mine':''}"><small>${e(playerName(m.from))}${m.channel==='gm'?' · private':''} · ${time(m.createdAt)}</small><p>${e(m.body)}</p></div>`).join(''):blank('Nothing said yet.','Send the first message.','message')}</div><form id="send-message" class="message-compose"><label class="grow m0"><span class="sr-only">Message</span><textarea name="body" id="message-body" maxlength="3000" placeholder="${chatChannel==='party'?'Message the party…':isGM()?'Whisper to the selected player…':'Whisper to your GM…'}" rows="2" required></textarea></label><button class="btn primary" type="submit">${icon('send')}<span class="send-text"> Send</span></button></form><p class="field-help mt8 mb0">Messages are saved even if the recipient is offline. Private chats are filtered server-side by the chosen role and name, not by verified identity.</p></div>`;}
function journalView(){const c=currentChar();return `<div class="page-title"><div><div class="eyebrow">The details matter</div><h1>Your journal.</h1><p>Equipment, notes, and the things your character won’t forget.</p></div>${characterPicker()}</div>${c?`<div class="grid2"><div class="card"><div class="row between mb"><h2 class="m0">Character notes</h2>${button(icon('edit'),'edit-notes','small ghost',`data-id="${e(c.id)}" data-field="notes" aria-label="Edit notes"`)}</div><div class="notes-text">${e(c.notes||'No notes yet.')}</div></div><div class="card"><div class="row between mb"><h2 class="m0">Inventory & currency</h2>${button(icon('edit'),'edit-notes','small ghost',`data-id="${e(c.id)}" data-field="inventory" aria-label="Edit inventory"`)}</div><div class="notes-text">${e(c.inventory||'No equipment recorded yet.')}</div></div></div><div class="card mt"><h2>Custom fields</h2><div class="field-grid">${Object.entries(c.customFields||{}).map(([key,val])=>`<div class="field-box"><small>${e(key)}</small><strong>${e(val)}</strong></div>`).join('')}</div>${button(icon('edit')+' Edit custom fields','custom-fields','ghost mt',`data-id="${e(c.id)}"`)}</div><div class="row wrap mt">${button(icon('download')+' Export character','export-character','primary',`data-id="${e(c.id)}"`)}${button(icon('upload')+' Import character','import-character','ghost')}${button('Print current sheet','print-character','ghost')}${button(icon('trash')+' Delete character','delete-character','subtle danger',`data-id="${e(c.id)}"`)}</div>`:blank('Choose or create a character.','Your journal will be here when you’re ready.','book')}`;}
function gmView(){const g=V.currentGame,players=V.profiles.filter(p=>g.members.includes(p.id));return `<div class="page-title"><div><div class="eyebrow">Behind the screen</div><h1>You set the stakes.</h1><p>Players name their targets aloud. Set their AC here before they roll.</p></div>${button(icon('die')+' Request a roll','request-roll','primary')}</div><div class="content-grid"><section><div class="grid3 mb"><div class="metric"><div class="label">At this table</div><div class="value">${players.length}</div><small>players</small></div><div class="metric"><div class="label">Waiting on you</div><div class="value">${V.rolls.filter(r=>r.outcome==='pending').length}</div><small>unresolved attacks</small></div><div class="metric"><div class="label">Level requests</div><div class="value">${V.characters.filter(c=>c.pendingLevel).length}</div><small>pending approvals</small></div></div><div class="gm-grid">${players.map(p=>{const chars=V.characters.filter(c=>c.playerId===p.id),target=V.targets[g.id+':'+p.id],pending=V.rolls.filter(r=>r.playerId===p.id&&r.outcome==='pending'),online=V.online.some(x=>x.profileId===p.id);return `<article class="card gm-card"><div class="row mb"><span class="avatar">${e(initials(p.name))}</span><div class="grow"><h3>${e(p.name)}</h3><span class="small ${online?'success':'muted'}">${online?'Connected':'Away'}</span></div>${icon('shield')}</div>${chars.length?chars.map(c=>{const d=derive(c);return `<div class="character-line"><div><strong>${e(c.name)}</strong><div class="small muted">${isDnd(c.system)?c.classes.map(x=>e(x.name)+' '+x.level).join(' / '):e(c.archetype)} · ${Math.max(0,d.maxHP-c.damage)}/${d.maxHP} HP</div>${c.pendingLevel?`<div class="row gap6 mt8"><span class="small gold">Level-up pending</span>${button('Review','review-level','small primary',`data-id="${e(c.id)}"`)}</div>`:''}</div>${button(icon('eye'),'gm-character','small ghost icon-only',`data-id="${e(c.id)}" aria-label="View ${e(c.name)}"`)}</div>`;}).join(''):'<div class="small muted">No character created yet.</div>'}<form class="ac-form" data-player="${e(p.id)}"><label>Target AC<input type="number" name="ac" min="-1000" max="10000" value="${target?.ac??''}" placeholder="AC" required></label><label>Target note (optional)<input name="label" value="${e(target?.label||'')}" maxlength="80" placeholder="Skeleton, bandit…"></label><button class="btn primary" type="submit">Set</button></form><div class="${target?.ac!==null&&target?.ac!==undefined?'target-ready':'target-none'}">${target?.ac!==null&&target?.ac!==undefined?`${icon('check')} Ready: AC ${e(target.ac)}${target.label?' · '+e(target.label):''}`:'No AC set. New attacks will wait for you.'}</div>${target?.ac!==null&&target?.ac!==undefined?button('Clear target','clear-target','subtle small',`data-player="${e(p.id)}"`):''}${pending.map(r=>`<div class="pending-roll"><strong class="small">${e(r.characterName)} · ${e(r.label)}</strong><div class="small gold">Attack total: ${e(r.total)} · Waiting for AC</div>${button('Resolve this roll','resolve-roll','small primary',`data-id="${e(r.id)}"`)}</div>`).join('')}</article>`;}).join('')}</div>${!players.length?`<div class="card">${blank('The table is open.','Players can choose their name and join this game. Leave this GM screen open to appear as active.','people')}</div>`:''}<div class="notice mt"><strong>A tie hits.</strong> Total ≥ AC is a hit. Natural 1 / 20 exceptions can be toggled in Game settings. AC is sent only to screens currently in GM mode.</div></section><aside class="right-column">${quickFeed()}<div class="card mt"><h3>Table controls</h3>${button(icon('gear')+' Game settings','game-settings','ghost wide')}${button(icon('download')+' Export game backup','export-game','ghost wide mt8')}</div></aside></div>`;}
function rollFeedView(){return `<div class="page-title"><div><div class="eyebrow">Every roll, in one place</div><h1>The roll ledger.</h1><p>Dice, modifiers, targets, and results. No disappearing math.</p></div>${button(icon('die')+' Request a roll','request-roll','primary')}</div><div class="grid2"><div class="card"><h2>Party rolls</h2>${V.rolls.length?V.rolls.slice().reverse().map(r=>rollHTML(r,true)).join(''):blank('The dice are quiet.','Your party’s rolls appear here as they happen.','die')}</div><section><form id="free-roll" class="card"><h2>GM dice tray</h2><label>Roll name<input name="label" placeholder="Encounter roll" value="GM roll" maxlength="100"></label><label>Formula<input name="formula" value="1d20 + 4" maxlength="100" required></label><label class="check-label"><input type="checkbox" name="private" checked> Keep this roll on GM screens only</label><button type="submit" class="btn primary wide">${icon('die')} Roll</button></form></section></div>`;}
function encounterView(){const g=V.currentGame;return `<div class="page-title"><div><div class="eyebrow">One turn at a time</div><h1>The encounter.</h1><p>Manual initiative and turn tracking, without a map to manage.</p></div><div class="row"><span class="pill gold">Round ${g.round}</span>${button('Next turn '+icon('arrow'),'next-turn','primary',g.initiative.length?'':'disabled')}</div></div><div class="grid2"><div class="card"><h2>Initiative order</h2>${g.initiative.length?g.initiative.map((x,i)=>`<div class="initiative-row ${g.turn===i?'active':''}"><span class="initiative-score">${x.score}</span><div class="grow"><strong>${e(x.name)}</strong>${x.hp?`<div class="small muted">HP note: ${e(x.hp)}</div>`:''}</div>${g.turn===i?'<span class="pill gold">Acting</span>':''}${button(icon('trash'),'remove-initiative','subtle small icon-only',`data-id="${e(x.id)}" aria-label="Remove combatant"`)}</div>`).join(''):blank('No combatants yet.','Add players and enemies, then advance the turn.','sword')}${button('Clear encounter','clear-encounter','subtle small mt')}</div><form id="initiative-form" class="card"><h2>Add a combatant</h2><label>Name<input name="name" placeholder="Character or enemy name" maxlength="80" required list="combatant-names"><datalist id="combatant-names">${V.characters.map(c=>`<option value="${e(c.name)}"></option>`).join('')}</datalist></label><div class="grid2"><label>Initiative total<input type="number" name="score" value="10" min="-1000" max="10000" required></label><label>HP note (optional)<input name="hp" maxlength="20" placeholder="35 / 35"></label></div><button class="btn primary wide" type="submit">${icon('plus')} Add to encounter</button></form></div>`;}
function gmNotesView(){return `<div class="page-title"><div><div class="eyebrow">For your eyes only</div><h1>Behind the curtain.</h1><p>Session notes for screens currently in GM mode.</p></div></div><form id="gm-notes" class="card"><label>GM notes<textarea name="notes" style="min-height:380px" maxlength="20000" placeholder="Encounters, secrets, names you will definitely remember this time…">${e(V.currentGame.notes||'')}</textarea></label><button class="btn primary" type="submit">Save GM notes</button><p class="field-help mt8 mb0">This is a trusted-group app. Any visitor able to select a GM name can read these notes. Do not store sensitive personal information.</p></form>`;}
function connectionModal(){const cfg=store?.config||window.TABLEBOUND_CONFIG||{};showModal('Connect your table',`<div class="notice info mb">Empty connection fields run the local demo. A Supabase connection shares names, characters and games across devices. Your existing maintenance projects are not configured or changed by this package.</div><form id="connection-form"><label>Supabase project URL<input name="supabaseUrl" type="url" placeholder="https://your-project.supabase.co" value="${e(cfg.supabaseUrl||'')}" autocomplete="off"></label><label>Publishable key<input name="publishableKey" placeholder="sb_publishable_…" value="${e(cfg.publishableKey||'')}" autocomplete="off" spellcheck="false"></label><p class="field-help">This key is public by design. Never enter a service_role, sb_secret, or image-provider secret here. The SQL setup and table-api function must be installed first.</p><div class="row wrap">${button(icon('download')+' Download config.js','download-config','ghost')}${button('Use local demo','use-demo','ghost')}${button('Reset demo data','reset-demo','subtle danger')}</div>${formFooter('Save connection & reload')}</form><div class="divider"></div><p class="small muted mb0">Shared play uses Supabase polling every 2.5 seconds. GM presence expires after about 65 seconds without a heartbeat. Keep the GM screen in the foreground during play.</p>`);}
function coverageModal(){showModal('Rules coverage · v'+VERSION,`<div class="notice mb">A playable first build, not a complete licensed replacement for every rulebook. Supported calculations are shown below; everything else remains editable.</div><table class="support-table"><thead><tr><th>System</th><th>Included</th></tr></thead><tbody><tr><td>D&D 5e 2014 & 2024</td><td>12 core class templates; class levels; HP, proficiency, skill/save modifiers, equipment AC, ability-based attacks, standard full/half/pact slots, core resources, ASI/feat and subclass prompts, level preview and undo.</td></tr><tr><td>Pathfinder 2e Remaster</td><td>Editable character fields, custom attacks, stat dice and campaign tools. Proficiency scaling, degrees of success and advancement rules are manual.</td></tr><tr><td>Call of Cthulhu 7e</td><td>Characteristic template and basic percentile roll-under attack buttons. Skill growth, bonus/penalty dice, hard/extreme successes, sanity and opposed checks are manual.</td></tr><tr><td>Savage Worlds Adventure Edition</td><td>Attribute template; exploding trait and wild dice for saved attack buttons. Raises, critical failures, Edges, Hindrances and advancement are manual.</td></tr><tr><td>Universal / Homebrew</td><td>Custom stats, fields, attacks, formulas, features and manual advancement.</td></tr></tbody></table><h3 class="mt">Important limits</h3><p class="small muted">D&D subclass features, species traits, many class-level choices, class skill quotas, advanced multiclass interactions, spell preparation/known limits, equipment proficiencies, conditions, feat effects and conditional bonuses are not fully enforced. Custom choices are recorded, not interpreted from prose. The 181-name spell catalog is a starter catalog and uses baseline class suggestions; check edition-specific access with your rules source.</p><p class="small muted">2014 ancestry bonuses and traits need manual entry. 2024 SRD background +2/+1 and basic background skill/feat entries can be applied during creation. Hit Dice spending/recovery, death saves and special rest features are manual. Undo restores an earlier whole-sheet snapshot, not only the level number.</p><p class="small muted">The name picker is intentionally trust-based. A different person can select the same name or enter GM mode. Private information is filtered by the selected role; there is no verified identity or secure GM ownership.</p><div class="divider"></div><h3>Source & attribution</h3><p class="small muted">This work includes material taken from the System Reference Document 5.1 (“SRD 5.1”) by Wizards of the Coast LLC and available at https://dnd.wizards.com/resources/systems-reference-document. The SRD 5.1 is licensed under the Creative Commons Attribution 4.0 International License available at https://creativecommons.org/licenses/by/4.0/legalcode.</p><p class="small muted">This work includes material from the System Reference Document 5.2.1 (“SRD 5.2.1”) by Wizards of the Coast LLC, available at https://www.dndbeyond.com/srd. The SRD 5.2.1 is licensed under the Creative Commons Attribution 4.0 International License, available at https://creativecommons.org/licenses/by/4.0/legalcode.</p><p class="small muted mb0">Numerical rules are adapted into original code, with condensed metadata and manual overrides. Other system names identify compatibility templates only; no proprietary rulebook text or artwork is included. See LICENSES.md in the package.</p>`);}
function createGameModal(){showModal('Create a game',`<form id="create-game-form"><label>Game name<input name="name" placeholder="Friday night campaign" maxlength="80" required></label><label>Rules system<select name="system">${opts(Object.entries(SYSTEMS).map(([value,s])=>({value,label:s.name+' · '+s.badge})),'dnd24')}</select></label><label>A little about the game<textarea name="description" placeholder="A sentence to help players find the right table." maxlength="400"></textarea></label>${formFooter('Create & enter game')}</form>`);}
function newCharacterModal(){const system=V.currentGame.system,stats=SYSTEMS[system].stats,dnd=isDnd(system);const classes=dnd?Object.keys(CLASSES):system==='pf2'?['Alchemist','Barbarian','Bard','Champion','Cleric','Druid','Fighter','Monk','Ranger','Rogue','Sorcerer','Witch','Wizard']:['Adventurer','Warrior','Scholar','Scout','Healer'];showModal('Create your character',`<form id="create-character-form"><span class="pill gold mb">${e(SYSTEMS[system].name)}</span>${isGM()?`<label>Player<select name="playerId" required>${opts(V.profiles.filter(p=>p.role==='player').map(p=>({value:p.id,label:p.name})),'','Choose a player')}</select></label>`:''}<label>Character name<input name="name" placeholder="Give your character a name" maxlength="80" required></label><div class="grid2">${customSelect('className',dnd?'Class':'Class / archetype',classes,dnd?'Fighter':'Adventurer')}${customSelect('species',system==='dnd14'?'Race / ancestry':'Species / ancestry',SPECIES[system]||[],'Human')}${customSelect('background',system==='coc7'?'Occupation':'Background',BACKGROUNDS[system]||[],system==='dnd24'?'Soldier':'')}</div><fieldset><legend>${system==='swade'?'Attribute die sizes':'Starting stats'}</legend><div class="grid3 stats-edit">${stats.map((s,i)=>`<label>${e(s)}<input name="stat_${e(s)}" type="number" min="-1000" max="10000" value="${system==='coc7'?50:system==='swade'?4:[15,14,13,12,10,8][i]||10}" required></label>`).join('')}</div><p class="field-help mb0">${dnd?'Start with the standard array shown here, enter scores, or replace scores later using the stat roller.':'These are editable placeholders, not automatically rolled starting characteristics.'}${system==='dnd14'?' Enter final scores including your ancestry bonuses. Ancestry traits are not applied automatically.':''}</p>${!dnd?'<label class="mt">Additional stats (one NAME=VALUE per line)<textarea name="extraStats" placeholder="Luck=50"></textarea></label>':''}</fieldset>${system==='dnd24'?`<fieldset><legend>Background bonuses</legend><label class="check-label"><input type="checkbox" name="applyBackground" id="apply-background"> Apply the selected SRD background’s +2 / +1, skills and feat</label><div class="grid2"><label>+2 ability<select name="boostOne">${opts(stats,'STR')}</select></label><label>+1 ability<select name="boostTwo">${opts(stats,'CON')}</select></label></div><p class="field-help mb0">Choose different abilities allowed by that background. Acolyte: INT/WIS/CHA; Criminal: DEX/CON/INT; Sage: CON/INT/WIS; Soldier: STR/DEX/CON. Uncheck this when your entered stats already include the bonuses. Custom backgrounds are manual.</p></fieldset>`:''}<div class="notice">After creating the sheet, review your initial skills, class choices and features. Core calculations are automatic; starting equipment, species traits and conditional feature effects need your review.</div>${formFooter('Create character')}</form>`);}
function editCharacterModal(c){const dnd=isDnd(c.system),d=derive(c);const fields=[['ac','Armor Class',d.calculatedAC],['hp','Maximum HP',d.calculatedHP],['proficiency','Proficiency bonus',d.basePB],['initiative','Initiative',d.initiative],['spellAttack','Spell attack',0],['spellDC','Spell save DC',0]];showModal('Edit '+c.name,`<form id="edit-character-form"><input type="hidden" name="id" value="${e(c.id)}"><input type="hidden" name="revision" value="${c.revision}"><label>Character name<input name="name" value="${e(c.name)}" maxlength="80" required></label><div class="grid2">${customSelect('species','Species / ancestry',SPECIES[c.system]||[],c.species)}${customSelect('background','Background / occupation',BACKGROUNDS[c.system]||[],c.background)}</div><fieldset><legend>Ability scores</legend><div class="grid3 stats-edit">${Object.entries(c.stats).map(([stat,value])=>`<label>${e(stat)}<input type="number" name="stat_${e(stat)}" value="${e(value)}" min="-1000" max="10000" required></label>`).join('')}</div><label>Add extra stats (one NAME=VALUE per line)<textarea name="extraStats" placeholder="Luck=10" style="min-height:65px"></textarea></label><p class="field-help mb0">These are your final scores. Changing CON recalculates maximum HP for all D&D levels. Existing overrides stay in place.</p></fieldset><fieldset><legend>${dnd?'Equipment & defense':'Manual system values'}</legend><div class="grid2">${dnd?`<label>Armor / AC calculation<select name="armor">${opts(Object.keys(ARMORS),c.armor)}</select></label><label>Speed<input name="speed" type="number" min="0" max="10000" value="${c.speed||30}"></label>`:`<label>Maximum HP<input name="manualHP" type="number" min="1" max="10000" value="${c.manualHP||10}"></label><label>Defense / AC<input name="manualAC" type="number" min="-1000" max="10000" value="${c.manualAC??10}"></label><label>Initiative modifier<input name="manualInitiative" type="number" min="-1000" max="10000" value="${c.manualInitiative||0}"></label><label>Class / archetype<input name="archetype" value="${e(c.archetype)}"></label>`}</div>${dnd?`<label class="check-label"><input name="shield" type="checkbox" ${c.shield?'checked':''}> Shield equipped (+2 AC, except Monk defense)</label><p class="field-help mb0">Armor proficiency, Strength requirements and whether your class allows a defense formula need manual review. Use the AC override below for custom armor.</p>`:''}</fieldset><fieldset><legend>Manual overrides</legend><p class="field-help">Adjustment adds to the calculated value. Fixed replaces it. Auto removes the override. For spell values, an adjustment applies separately to each casting class.</p>${fields.filter(([key])=>dnd||['ac','hp','initiative'].includes(key)).map(([key,label,base])=>{const o=c.overrides?.[key]||{mode:'auto',value:0};return `<div class="grid3"><label>${e(label)}<select name="override_${key}_mode">${opts([{value:'auto',label:'Automatic'},{value:'adjustment',label:'Adjustment (+ / −)'},{value:'fixed',label:'Fixed value'}],o.mode)}</select></label><label>Value<input name="override_${key}_value" type="number" min="-10000" max="10000" value="${o.value||0}"></label><label>Reason<input name="override_${key}_reason" value="${e(o.reason||'')}" maxlength="200" placeholder="Item, house rule…"></label></div>`;}).join('')}</fieldset>${formFooter('Save character')}</form>`,{character:clone(c)});}
function editSkillsModal(c){showModal('Skills & saving throws',`<form id="skills-form"><div class="grid2">${Object.keys(SKILLS).map(skill=>`<label>${e(skill)}<select name="skill_${e(skill)}">${opts([{value:0,label:'Not proficient'},{value:.5,label:'Half proficiency'},{value:1,label:'Proficient'},{value:2,label:'Expertise'}],c.skills[skill]||0)}</select></label>`).join('')}</div><fieldset><legend>Saving-throw proficiencies</legend><div class="grid3">${Object.keys(c.stats).map(stat=>`<label class="check-label"><input type="checkbox" name="save_${e(stat)}" ${c.saves.includes(stat)?'checked':''}>${e(stat)}</label>`).join('')}</div></fieldset><p class="field-help">Choose the skills granted by your class, background and other features. This editor does not enforce class skill quotas.</p>${formFooter()}</form>`,{character:clone(c)});}
function attackModal(c,attackId){const a=c.attacks.find(x=>x.id===attackId)||{id:uid(),name:'',stat:isDnd(c.system)?'STR':'',proficient:true,bonus:0,damage:'1d8',damageBonus:0,addStatDamage:isDnd(c.system),sides:6,threshold:50};showModal(attackId?'Edit ability / attack':'Add ability / attack',`<form id="attack-form">${isDnd(c.system)?`<label>Start from a weapon<select id="weapon-template">${opts(Object.keys(WEAPONS),a.name,'Custom ability / spell attack')}</select></label>`:''}<label>Attack / ability name<input name="name" value="${e(a.name)}" maxlength="80" placeholder="Longsword, Fire Bolt, claw…" required></label><div class="grid2">${isDnd(c.system)?`<label>Governing ability<select name="stat">${opts([...Object.keys(c.stats),{value:'finesse',label:'Finesse (higher STR / DEX)'},{value:'',label:'None / use fixed modifier'}],a.stat)}</select></label>`:c.system==='coc7'?`<label>Percentile skill target<input name="threshold" type="number" min="1" max="100" value="${a.threshold||50}" required></label>`:c.system==='swade'?`<label>Trait die<select name="sides">${opts([4,6,8,10,12].map(n=>({value:n,label:'d'+n})),a.sides||6)}</select></label>`:''}<label>${isDnd(c.system)?'Additional attack modifier':'Full attack modifier'}<input name="bonus" type="number" min="-1000" max="1000" value="${a.bonus||0}"></label><label>Damage formula<input name="damage" value="${e(a.damage)}" placeholder="1d8" maxlength="100" required></label><label>Extra flat damage<input name="damageBonus" type="number" min="-1000" max="1000" value="${a.damageBonus||0}"></label></div>${customSelect('type','Damage type',['Bludgeoning','Piercing','Slashing','Acid','Cold','Fire','Force','Lightning','Necrotic','Poison','Psychic','Radiant','Thunder'],a.type||'')}${isDnd(c.system)?`<label class="check-label"><input type="checkbox" name="proficient" ${a.proficient?'checked':''}> Add proficiency to attack</label><label class="check-label"><input type="checkbox" name="addStatDamage" ${a.addStatDamage?'checked':''}> Add ability modifier to damage</label><label class="check-label"><input type="checkbox" name="ranged" ${a.ranged?'checked':''}> Ranged weapon (applies Archery style when selected)</label><label class="check-label"><input type="checkbox" name="dueling" ${a.dueling?'checked':''}> Eligible for Dueling style (+2 damage when selected)</label>`:''}<p class="field-help">For automatic-damage spells or non-attack abilities, use the Damage button or the general dice tray. Cantrip scaling, multi-target effects and conditional bonuses are manual.</p>${attackId?button(icon('trash')+' Remove this ability','remove-attack','subtle danger',`data-id="${e(c.id)}" data-attack="${e(a.id)}"`):''}${formFooter(attackId?'Save ability':'Add ability')}</form>`,{character:clone(c),attack:clone(a)});}
function hpModal(c){const d=derive(c);showModal('Hit points · '+c.name,`<form id="hp-form"><div class="metric mb"><div class="label">Current / maximum</div><div class="value">${Math.max(0,d.maxHP-c.damage)} / ${d.maxHP}</div></div><div class="grid2"><label>Change HP<input type="number" name="delta" min="-10000" max="10000" value="0" required><span class="field-help">Negative takes damage, positive heals.</span></label><label>Temporary HP (set total)<input type="number" name="temp" min="0" max="10000" value="${c.tempHP||0}" required></label></div><p class="field-help">Damage uses temporary HP first. Healing does not exceed maximum HP. Death saves and effects at zero HP are handled at the table.</p>${formFooter('Apply HP change')}</form>`,{character:clone(c)});}
