function fieldsModal(c){showModal('Custom character fields',`<form id="fields-form"><label>One name=value per line<textarea name="fields" style="min-height:270px" maxlength="12000" placeholder="Luck=60\nSanity=45\nLanguages=Common, Dwarvish">${e(Object.entries(c.customFields||{}).map(([k,v])=>k+'='+v).join('\n'))}</textarea></label><p class="field-help">Add any resources or details your game uses. These are stored as text. Add mathematical effects separately through an override or saved ability.</p>${formFooter()}</form>`,{character:clone(c)});}
function featureModal(c){showModal('Add a custom feature',`<form id="feature-form"><label>Name<input name="name" placeholder="Feature, class choice, boon…" maxlength="120" required></label><label>Notes / mechanical effects<textarea name="notes" maxlength="4000" placeholder="Describe the feature, its trigger and how to use it."></textarea></label><div class="notice">This records the feature. It does not execute rules written in prose. Set numerical effects in the character’s overrides or add a saved ability button.</div>${formFooter('Add feature')}</form>`,{character:clone(c)});}
